# function to get input from terminal -- overridden by the test suite
# Arguments are positional-only to match ``input``.
def term_input(prompt: str, /) -> str:
    if sys.platform == 'win32':
        # Important: On windows, readline is not enabled by default.  In these
        #            environment, escape sequences have been broken.  To avoid the
        #            problem, quickstart uses ``print()`` to show prompt.
        print(prompt, end='')
        return input('')
    else:
        return input(prompt)


class ValidationError(Exception):
    """Raised for validation errors."""


def is_path(x: str) -> str:
    x = os.path.expanduser(x)
    if not os.path.isdir(x):
        raise ValidationError(__('Please enter a valid path name.'))
    return x


def is_path_or_empty(x: str) -> str:
    if not x:
        return ''
    return is_path(x)


def allow_empty(x: str) -> str:
    return x


def nonempty(x: str) -> str:
    if not x:
        raise ValidationError(__('Please enter some text.'))
    return x


def choice(*l: str) -> Callable[[str], str]:
    def val(x: str) -> str:
        if x not in l:
            raise ValidationError(__('Please enter one of %s.') % ', '.join(l))
        return x

    return val


def boolean(x: str) -> bool:
    if x.upper() not in {'Y', 'YES', 'N', 'NO'}:
        raise ValidationError(__("Please enter either 'y' or 'n'."))
    return x.upper() in {'Y', 'YES'}


def suffix(x: str) -> str:
    if not (x[0:1] == '.' and len(x) > 1):
        raise ValidationError(__("Please enter a file suffix, e.g. '.rst' or '.txt'."))
    return x


def ok(x: str) -> str:
    return x


def do_prompt(
    text: str,
    default: str | None = None,
    validator: Callable[[str], Any] = nonempty,
) -> str | bool:
    while True:
        if default is not None:
            prompt = PROMPT_PREFIX + f'{text} [{default}]: '
        else:
            prompt = PROMPT_PREFIX + text + ': '
        if USE_LIBEDIT:
            # Note: libedit has a problem for combination of ``input()``
            # and escape sequences.
            # To avoid the problem, all prompts are not colored on libedit.
            # See https://github.com/sphinx-doc/sphinx/issues/5335
            pass
        else:
            prompt = _question_colour(prompt)
        x = term_input(prompt).strip()
        if default and not x:
            x = default
        try:
            x = validator(x)
        except ValidationError as err:
            print(red('* ' + str(err)))
            continue
        break
    return x


class QuickstartRenderer(SphinxRenderer):
    def __init__(self, templatedir: str = '') -> None:
        self.templatedir = templatedir
        super().__init__()

    def _has_custom_template(self, template_name: str) -> bool:
        """Check if custom template file exists.

        Note: Please don't use this function from extensions.
              It will be removed in the future without deprecation period.
        """
        template = os.path.join(self.templatedir, os.path.basename(template_name))
        return bool(self.templatedir) and os.path.exists(template)

    def render(self, template_name: str, context: dict[str, Any]) -> str:
        if self._has_custom_template(template_name):
            custom_template = os.path.join(
                self.templatedir, os.path.basename(template_name)
            )
            return self.render_from_file(custom_template, context)
        else:
            return super().render(template_name, context)


def ask_user(d: dict[str, Any]) -> None:
    """Ask the user for quickstart values missing from *d*.

    Values are:

    * path:      root path
    * sep:       separate source and build dirs (bool)
    * dot:       replacement for dot in _templates etc.
    * project:   project name
    * author:    author names
    * version:   version of project
    * release:   release of project
    * language:  document language
    * suffix:    source file suffix
    * master:    master document name
    * extensions:  extensions to use (list)
    * makefile:  make Makefile
    * batchfile: make command file
    """
    print(
        bold(__('Welcome to the Sphinx %s quickstart utility.')) % __display_version__
    )
    print()
    print(
        __(
            'Please enter values for the following settings (just press Enter to\n'
            'accept a default value, if one is given in brackets).'
        )
    )

    if 'path' in d:
        print()
        print(bold(__('Selected root path: %s')) % d['path'])
    else:
        print()
        print(__('Enter the root path for documentation.'))
        d['path'] = do_prompt(__('Root path for the documentation'), '.', is_path)

    while os.path.isfile(os.path.join(d['path'], 'conf.py')) or os.path.isfile(
        os.path.join(d['path'], 'source', 'conf.py')
    ):
        print()
        print(
            bold(
                __(
                    'Error: an existing conf.py has been found in the '
                    'selected root path.'
                )
            )
        )
        print(__('sphinx-quickstart will not overwrite existing Sphinx projects.'))
        print()
        d['path'] = do_prompt(
            __('Please enter a new root path (or just Enter to exit)'),
            '',
            is_path_or_empty,
        )
        if not d['path']:
            raise SystemExit(1)

    if 'sep' not in d:
        print()
        print(
            __(
                'You have two options for placing the build directory for Sphinx output.\n'
                'Either, you use a directory "_build" within the root path, or you separate\n'
                '"source" and "build" directories within the root path.'
            )
        )
        d['sep'] = do_prompt(
            __('Separate source and build directories (y/n)'), 'n', boolean
        )

    if 'dot' not in d:
        print()
        print(
            __(
                'Inside the root directory, two more directories will be created; "_templates"\n'  # NoQA: E501
                'for custom HTML templates and "_static" for custom stylesheets and other static\n'  # NoQA: E501
                'files. You can enter another prefix (such as ".") to replace the underscore.'
            )
        )
        d['dot'] = do_prompt(__('Name prefix for templates and static dir'), '_', ok)

    if 'project' not in d:
        print()
        print(
            __(
                'The project name will occur in several places in the built documentation.'
            )
        )
        d['project'] = do_prompt(__('Project name'))
    if 'author' not in d:
        d['author'] = do_prompt(__('Author name(s)'))

    if 'version' not in d:
        print()
        print(
            __(
                'Sphinx has the notion of a "version" and a "release" for the\n'
                'software. Each version can have multiple releases. For example, for\n'
                'Python the version is something like 2.5 or 3.0, while the release is\n'
                "something like 2.5.1 or 3.0a1. If you don't need this dual structure,\n"
                'just set both to the same value.'
            )
        )
        d['version'] = do_prompt(__('Project version'), '', allow_empty)
    if 'release' not in d:
        d['release'] = do_prompt(__('Project release'), d['version'], allow_empty)

    if 'language' not in d:
        print()
        print(
            __(
                'If the documents are to be written in a language other than English,\n'
                'you can select a language here by its language code. Sphinx will then\n'
                'translate text that it generates into that language.\n'
                '\n'
                'For a list of supported codes, see\n'
                'https://www.sphinx-doc.org/en/master/usage/configuration.html#confval-language.',
            )
        )
        d['language'] = do_prompt(__('Project language'), 'en')
        if d['language'] == 'en':
            d['language'] = None

    if 'suffix' not in d:
        print()
        print(
            __(
                'The file name suffix for source files. Commonly, this is either ".txt"\n'
                'or ".rst". Only files with this suffix are considered documents.'
            )
        )
        d['suffix'] = do_prompt(__('Source file suffix'), '.rst', suffix)

    if 'master' not in d:
        print()
        print(
            __(
                'One document is special in that it is considered the top node of the\n'
                '"contents tree", that is, it is the root of the hierarchical structure\n'
                'of the documents. Normally, this is "index", but if your "index"\n'
                'document is a custom template, you can also set this to another filename.'
            )
        )
        d['master'] = do_prompt(
            __('Name of your master document (without suffix)'), 'index'
        )

    while (
        os.path.isfile(os.path.join(d['path'], d['master'] + d['suffix']))
        or os.path.isfile(os.path.join(d['path'], 'source', d['master'] + d['suffix']))
    ):  # fmt: skip
        print()
        print(
            bold(
                __(
                    'Error: the master file %s has already been found in the '
                    'selected root path.'
                )
                % (d['master'] + d['suffix'])
            )
        )
        print(__('sphinx-quickstart will not overwrite the existing file.'))
        print()
        d['master'] = do_prompt(
            __(
                'Please enter a new file name, or rename the '
                'existing file and press Enter'
            ),
            d['master'],
        )

    if 'extensions' not in d:
        print(
            __('Indicate which of the following Sphinx extensions should be enabled:')
        )
        d['extensions'] = []
        for name, description in EXTENSIONS.items():
            if do_prompt(f'{name}: {description} (y/n)', 'n', boolean):
                d['extensions'].append('sphinx.ext.%s' % name)

        # Handle conflicting options
        if {'sphinx.ext.imgmath', 'sphinx.ext.mathjax'}.issubset(d['extensions']):
            print(
                __(
                    'Note: imgmath and mathjax cannot be enabled at the same time. '
                    'imgmath has been deselected.'
                )
            )
            d['extensions'].remove('sphinx.ext.imgmath')

    if 'makefile' not in d:
        print()
        print(
            __(
                'A Makefile and a Windows command file can be generated for you so that you\n'
                "only have to run e.g. `make html' instead of invoking sphinx-build\n"
                'directly.'
            )
        )
        d['makefile'] = do_prompt(__('Create Makefile? (y/n)'), 'y', boolean)

    if 'batchfile' not in d:
        d['batchfile'] = do_prompt(
            __('Create Windows command file? (y/n)'), 'y', boolean
        )
    print()


def generate(
    d: dict[str, Any],
    overwrite: bool = True,
    silent: bool = False,
    templatedir: str | None = None,
) -> None:
    """Generate project based on values in *d*."""
    template = QuickstartRenderer(templatedir or '')

    if 'mastertoctree' not in d:
        d['mastertoctree'] = ''
    if 'mastertocmaxdepth' not in d:
        d['mastertocmaxdepth'] = 2

    d['root_doc'] = d['master']
    d['now'] = time.asctime()
    d['project_underline'] = column_width(d['project']) * '='
    d.setdefault('extensions', [])
    d['copyright'] = time.strftime('%Y') + ', ' + d['author']

    d['path'] = os.path.abspath(d['path'])
    ensuredir(d['path'])

    srcdir = os.path.join(d['path'], 'source') if d['sep'] else d['path']

    ensuredir(srcdir)
    if d['sep']:
        builddir = os.path.join(d['path'], 'build')
        d['exclude_patterns'] = ''
    else:
        builddir = os.path.join(srcdir, d['dot'] + 'build')
        exclude_patterns = map(
            repr,
            [
                d['dot'] + 'build',
                'Thumbs.db',
                '.DS_Store',
            ],
        )
        d['exclude_patterns'] = ', '.join(exclude_patterns)
    ensuredir(builddir)
    ensuredir(os.path.join(srcdir, d['dot'] + 'templates'))
    ensuredir(os.path.join(srcdir, d['dot'] + 'static'))

    def write_file(fpath: str, content: str, newline: str | None = None) -> None:
        if overwrite or not os.path.isfile(fpath):
            if 'quiet' not in d:
                print(__('Creating file %s.') % fpath)
            with open(fpath, 'w', encoding='utf-8', newline=newline) as f:
                f.write(content)
        else:
            if 'quiet' not in d:
                print(__('File %s already exists, skipping.') % fpath)

    conf_path = os.path.join(templatedir, 'conf.py.jinja') if templatedir else None
    if not conf_path or not os.path.isfile(conf_path):
        conf_path = os.path.join(
            package_dir, 'templates', 'quickstart', 'conf.py.jinja'
        )
    with open(conf_path, encoding='utf-8') as f:
        conf_text = f.read()

    write_file(os.path.join(srcdir, 'conf.py'), template.render_string(conf_text, d))

    masterfile = os.path.join(srcdir, d['master'] + d['suffix'])
    if template._has_custom_template('quickstart/master_doc.rst.jinja'):
        write_file(masterfile, template.render('quickstart/master_doc.rst.jinja', d))
    else:
        write_file(masterfile, template.render('quickstart/root_doc.rst.jinja', d))

    makefile_template = 'quickstart/Makefile.new.jinja'
    batchfile_template = 'quickstart/make.bat.new.jinja'

    if d['makefile'] is True:
        d['rsrcdir'] = 'source' if d['sep'] else '.'
        d['rbuilddir'] = 'build' if d['sep'] else d['dot'] + 'build'
        # use binary mode, to avoid writing \r\n on Windows
        write_file(
            os.path.join(d['path'], 'Makefile'),
            template.render(makefile_template, d),
            '\n',
        )

    if d['batchfile'] is True:
        d['rsrcdir'] = 'source' if d['sep'] else '.'
        d['rbuilddir'] = 'build' if d['sep'] else d['dot'] + 'build'
        write_file(
            os.path.join(d['path'], 'make.bat'),
            template.render(batchfile_template, d),
            '\r\n',
        )

    if silent:
        return
    print()
    print(bold(__('Finished: An initial directory structure has been created.')))
    print()
    print(
        __(
            'You should now populate your master file %s and create other documentation\n'
            'source files. '
        )
        % masterfile,
        end='',
    )
    if d['makefile'] or d['batchfile']:
        print(__('Use the Makefile to build the docs, like so:\n   make builder'))
    else:
        print(
            __(
                'Use the sphinx-build command to build the docs, like so:\n'
                '   sphinx-build -b builder %s %s'
            )
            % (srcdir, builddir)
        )
    print(
        __(
            'where "builder" is one of the supported builders, '
            'e.g. html, latex or linkcheck.'
        )
    )
    print()


def valid_dir(d: dict[str, Any]) -> bool:
    dir = d['path']
    if not os.path.exists(dir):
        return True
    if not os.path.isdir(dir):
        return False

    if {'Makefile', 'make.bat'} & set(os.listdir(dir)):
        return False

    if d['sep']:
        dir = os.path.join('source', dir)
        if not os.path.exists(dir):
            return True
        if not os.path.isdir(dir):
            return False

    reserved_names = [
        'conf.py',
        d['dot'] + 'static',
        d['dot'] + 'templates',
        d['master'] + d['suffix'],
    ]
    return not set(reserved_names) & set(os.listdir(dir))


def get_parser() -> argparse.ArgumentParser:
    description = __(
        '\n'
        'Generate required files for a Sphinx project.\n'
        '\n'
        'sphinx-quickstart is an interactive tool that asks some questions about your\n'
        'project and then generates a complete documentation directory and sample\n'
        'Makefile to be used with sphinx-build.\n',
    )
    parser = argparse.ArgumentParser(
        usage='%(prog)s [OPTIONS] <PROJECT_DIR>',
        epilog=__('For more information, visit <https://www.sphinx-doc.org/>.'),
        description=description,
    )

    parser.add_argument(
        '-q',
        '--quiet',
        action='store_true',
        dest='quiet',
        default=None,
        help=__('quiet mode'),
    )
    parser.add_argument(
        '--version',
        action='version',
        dest='show_version',
        version='%%(prog)s %s' % __display_version__,
    )

    parser.add_argument(
        'path', metavar='PROJECT_DIR', default='.', nargs='?', help=__('project root')
    )

    group = parser.add_argument_group(__('Structure options'))
    group.add_argument(
        '--sep',
        action='store_true',
        dest='sep',
        default=None,
        help=__('if specified, separate source and build dirs'),
    )
    group.add_argument(
        '--no-sep',
        action='store_false',
        dest='sep',
        help=__('if specified, create build dir under source dir'),
    )
    group.add_argument(
        '--dot',
        metavar='DOT',
        default='_',
        help=__('replacement for dot in _templates etc.'),
    )

    group = parser.add_argument_group(__('Project basic options'))
    group.add_argument(
        '-p', '--project', metavar='PROJECT', dest='project', help=__('project name')
    )
    group.add_argument(
        '-a', '--author', metavar='AUTHOR', dest='author', help=__('author names')
    )
    group.add_argument(
        '-v',
        metavar='VERSION',
        dest='version',
        default='',
        help=__('version of project'),
    )
    group.add_argument(
        '-r',
        '--release',
        metavar='RELEASE',
        dest='release',
        help=__('release of project'),
    )
    group.add_argument(
        '-l',
        '--language',
        metavar='LANGUAGE',
        dest='language',
        help=__('document language'),
    )
    group.add_argument(
        '--suffix', metavar='SUFFIX', default='.rst', help=__('source file suffix')
    )
    group.add_argument(
        '--master', metavar='MASTER', default='index', help=__('master document name')
    )
    group.add_argument(
        '--epub', action='store_true', default=False, help=__('use epub')
    )

    group = parser.add_argument_group(__('Extension options'))
    for ext in EXTENSIONS:
        group.add_argument(
            '--ext-%s' % ext,
            action='append_const',
            const='sphinx.ext.%s' % ext,
            dest='extensions',
            help=__('enable %s extension') % ext,
        )
    group.add_argument(
        '--extensions',
        metavar='EXTENSIONS',
        dest='extensions',
        action='append',
        help=__('enable arbitrary extensions'),
    )

    group = parser.add_argument_group(__('Makefile and Batchfile creation'))
    group.add_argument(
        '--makefile',
        action='store_true',
        dest='makefile',
        default=True,
        help=__('create makefile'),
    )
    group.add_argument(
        '--no-makefile',
        action='store_false',
        dest='makefile',
        help=__('do not create makefile'),
    )
    group.add_argument(
        '--batchfile',
        action='store_true',
        dest='batchfile',
        default=True,
        help=__('create batchfile'),
    )
    group.add_argument(
        '--no-batchfile',
        action='store_false',
        dest='batchfile',
        help=__('do not create batchfile'),
    )
    # --use-make-mode is a no-op from Sphinx 8.
    group.add_argument(
        '-m',
        '--use-make-mode',
        action='store_true',
        dest='make_mode',
        default=True,
        help=__('use make-mode for Makefile/make.bat'),
    )

    group = parser.add_argument_group(__('Project templating'))
    group.add_argument(
        '-t',
        '--templatedir',
        metavar='TEMPLATEDIR',
        dest='templatedir',
        help=__('template directory for template files'),
    )
    group.add_argument(
        '-d',
        metavar='NAME=VALUE',
        action='append',
        dest='variables',
        help=__('define a template variable'),
    )

    return parser


def main(argv: Sequence[str] = (), /) -> int:
    locale.setlocale(locale.LC_ALL, '')
    sphinx.locale.init_console()

    if not terminal_supports_colour():
        disable_colour()

    # parse options
    parser = get_parser()
    try:
        args = parser.parse_args(argv or sys.argv[1:])
    except SystemExit as err:
        return err.code  # type: ignore[return-value]

    d = vars(args)
    # delete None or False value
    d = {k: v for k, v in d.items() if v is not None}

    # handle use of CSV-style extension values
    d.setdefault('extensions', [])
    for ext in d['extensions'][:]:
        if ',' in ext:
            d['extensions'].remove(ext)
            d['extensions'].extend(ext.split(','))

    try:
        if 'quiet' in d:
            if not {'project', 'author'}.issubset(d):
                print(
                    __(
                        '"quiet" is specified, but any of "project" or '
                        '"author" is not specified.'
                    )
                )
                return 1

        if {'quiet', 'project', 'author'}.issubset(d):
            # quiet mode with all required params satisfied, use default
            d.setdefault('version', '')
            d.setdefault('release', d['version'])
            d2 = DEFAULTS.copy()
            d2.update(d)
            d = d2

            if not valid_dir(d):
                print()
                print(
                    bold(
                        __(
                            'Error: specified path is not a directory, or sphinx'
                            ' files already exist.'
                        )
                    )
                )
                print(
                    __(
                        'sphinx-quickstart only generate into a empty directory.'
                        ' Please specify a new root path.'
                    )
                )
                return 1
        else:
            ask_user(d)
    except (KeyboardInterrupt, EOFError):
        print()
        print('[Interrupted.]')
        return 130  # 128 + SIGINT

    for variable in d.get('variables', []):  # type: ignore[union-attr]
        try:
            name, value = variable.split('=')
            d[name] = value
        except ValueError:
            print(__('Invalid template variable: %s') % variable)

    generate(d, overwrite=False, templatedir=args.templatedir)
    return 0


if __name__ == '__main__':
    raise SystemExit(main(sys.argv[1:]))

"""Toctree collector for sphinx.environment."""

from __future__ import annotations

from typing import TYPE_CHECKING, TypeVar, cast

from docutils import nodes

from sphinx import addnodes
from sphinx.domains.std import StandardDomain
from sphinx.environment.adapters.toctree import note_toctree
from sphinx.environment.collectors import EnvironmentCollector
from sphinx.locale import __
from sphinx.transforms import SphinxContentsFilter
from sphinx.util import logging, url_re

if TYPE_CHECKING:
    from collections.abc import Sequence, Set

    from docutils.nodes import Element, Node

    from sphinx.application import Sphinx
    from sphinx.environment import BuildEnvironment
    from sphinx.util.typing import ExtensionMetadata

N = TypeVar('N')

logger = logging.getLogger(__name__)


class TocTreeCollector(EnvironmentCollector):
    def clear_doc(self, app: Sphinx, env: BuildEnvironment, docname: str) -> None:
        env.tocs.pop(docname, None)
        env.toc_secnumbers.pop(docname, None)
        env.toc_fignumbers.pop(docname, None)
        env.toc_num_entries.pop(docname, None)
        env.toctree_includes.pop(docname, None)
        env.glob_toctrees.discard(docname)
        env.numbered_toctrees.discard(docname)

        for subfn, fnset in list(env.files_to_rebuild.items()):
            fnset.discard(docname)
            if not fnset:
                del env.files_to_rebuild[subfn]

    def merge_other(
        self,
        app: Sphinx,
        env: BuildEnvironment,
        docnames: Set[str],
        other: BuildEnvironment,
    ) -> None:
        for docname in docnames:
            env.tocs[docname] = other.tocs[docname]
            env.toc_num_entries[docname] = other.toc_num_entries[docname]
            if docname in other.toctree_includes:
                env.toctree_includes[docname] = other.toctree_includes[docname]
            if docname in other.glob_toctrees:
                env.glob_toctrees.add(docname)
            if docname in other.numbered_toctrees:
                env.numbered_toctrees.add(docname)

        for subfn, fnset in other.files_to_rebuild.items():
            env.files_to_rebuild.setdefault(subfn, set()).update(fnset & set(docnames))

    def process_doc(self, app: Sphinx, doctree: nodes.document) -> None:
        """Build a TOC from the doctree and store it in the inventory."""
        docname = app.env.current_document.docname
        numentries = [0]  # nonlocal again...

        def build_toc(
            node: Element | Sequence[Element],
            depth: int = 1,
        ) -> nodes.bullet_list | None:
            # list of table of contents entries
            entries: list[Element] = []
            for sectionnode in node:
                # find all toctree nodes in this section and add them
                # to the toc (just copying the toctree node which is then
                # resolved in self.get_and_resolve_doctree)
                if isinstance(sectionnode, nodes.section):
                    title = sectionnode[0]
                    # copy the contents of the section title, but without references
                    # and unnecessary stuff
                    visitor = SphinxContentsFilter(doctree)
                    title.walkabout(visitor)
                    nodetext = visitor.get_entry_text()  # type: ignore[no-untyped-call]
                    anchorname = _make_anchor_name(sectionnode['ids'], numentries)
                    # make these nodes:
                    # list_item -> compact_paragraph -> reference
                    reference = nodes.reference(
                        '',
                        '',
                        internal=True,
                        refuri=docname,
                        anchorname=anchorname,
                        *nodetext,
                    )
                    para = addnodes.compact_paragraph('', '', reference)
                    item: Element = nodes.list_item('', para)
                    sub_item = build_toc(sectionnode, depth + 1)
                    if sub_item:
                        item += sub_item
                    entries.append(item)
                # Wrap items under an ``.. only::`` directive in a node for
                # post-processing
                elif isinstance(sectionnode, addnodes.only):
                    onlynode = addnodes.only(expr=sectionnode['expr'])
                    blist = build_toc(sectionnode, depth)
                    if blist:
                        onlynode += blist.children
                        entries.append(onlynode)
                # check within the section for other node types
                elif isinstance(sectionnode, nodes.Element):
                    # cache of parent node -> list item
                    memo_parents: dict[nodes.Element, nodes.list_item] = {}
                    toctreenode: nodes.Node
                    for toctreenode in sectionnode.findall():
                        if isinstance(toctreenode, nodes.section):
                            continue
                        if isinstance(toctreenode, addnodes.toctree):
                            item = toctreenode.copy()
                            entries.append(item)
                            # important: do the inventory stuff
                            note_toctree(app.env, docname, toctreenode)
                        # add object signatures within a section to the ToC
                        elif isinstance(toctreenode, addnodes.desc):
                            # The desc has one or more nested desc_signature,
                            # and then a desc_content, which again may have desc nodes.
                            # Thus, desc is the one we can bubble up to through parents.
                            entry: nodes.list_item | None = None
                            for sig_node in toctreenode:
                                if not isinstance(sig_node, addnodes.desc_signature):
                                    continue
                                # Skip if no name set
                                if not sig_node.get('_toc_name', ''):
                                    continue
                                # Skip if explicitly disabled
                                if sig_node.parent.get('no-contents-entry'):
                                    continue
                                # Skip entries with no ID (e.g. with :no-index: set)
                                ids = sig_node['ids']
                                if not ids:
                                    continue

                                anchorname = _make_anchor_name(ids, numentries)

                                reference = nodes.reference(
                                    '',
                                    '',
                                    nodes.literal('', sig_node['_toc_name']),
                                    internal=True,
                                    refuri=docname,
                                    anchorname=anchorname,
                                )
                                para = addnodes.compact_paragraph(
                                    '', '', reference, skip_section_number=True
                                )
                                entry = nodes.list_item('', para)

                                # Find parent node
                                parent = sig_node.parent
                                while (
                                    parent not in memo_parents and parent != sectionnode
                                ):
                                    parent = parent.parent
                                # Note, it may both be the limit and in memo_parents,
                                # prefer memo_parents, so we get the nesting.
                                if parent in memo_parents:
                                    root_entry = memo_parents[parent]
                                    if isinstance(root_entry[-1], nodes.bullet_list):
                                        root_entry[-1].append(entry)
                                    else:
                                        root_entry.append(nodes.bullet_list('', entry))
                                else:
                                    assert parent == sectionnode
                                    entries.append(entry)

                            # Save the latest desc_signature as the one we put sub entries in.
                            # If there are multiple signatures, then the latest is used.
                            if entry is not None:
                                # are there any desc nodes without desc_signature nodes?
                                memo_parents[toctreenode] = entry

            if entries:
                return nodes.bullet_list('', *entries)
            return None

        toc = build_toc(doctree)
        if toc:
            app.env.tocs[docname] = toc
        else:
            app.env.tocs[docname] = nodes.bullet_list('')
        app.env.toc_num_entries[docname] = numentries[0]

    def get_updated_docs(self, app: Sphinx, env: BuildEnvironment) -> list[str]:
        return self.assign_section_numbers(env) + self.assign_figure_numbers(env)

    def assign_section_numbers(self, env: BuildEnvironment) -> list[str]:
        """Assign a section number to each heading under a numbered toctree."""
        # a list of all docnames whose section numbers changed
        rewrite_needed = []

        assigned: set[str] = set()
        old_secnumbers = env.toc_secnumbers
        env.toc_secnumbers = {}

        def _walk_toc(
            node: Element,
            secnums: dict[str, tuple[int, ...]],
            depth: int,
            titlenode: nodes.title | None = None,
        ) -> None:
            # titlenode is the title of the document, it will get assigned a
            # secnumber too, so that it shows up in next/prev/parent rellinks
            for subnode in node.children:
                if isinstance(subnode, nodes.bullet_list):
                    numstack.append(0)
                    _walk_toc(subnode, secnums, depth - 1, titlenode)
                    numstack.pop()
                    titlenode = None
                elif isinstance(subnode, nodes.list_item):
                    _walk_toc(subnode, secnums, depth, titlenode)
                    titlenode = None
                elif isinstance(subnode, addnodes.only):
                    # at this stage we don't know yet which sections are going
                    # to be included; just include all of them, even if it leads
                    # to gaps in the numbering
                    _walk_toc(subnode, secnums, depth, titlenode)
                    titlenode = None
                elif isinstance(subnode, addnodes.compact_paragraph):
                    if 'skip_section_number' in subnode:
                        continue
                    numstack[-1] += 1
                    reference = cast('nodes.reference', subnode[0])
                    if depth > 0:
                        number = numstack.copy()
                        secnums[reference['anchorname']] = tuple(numstack)
                    else:
                        number = None
                        secnums[reference['anchorname']] = ()
                    reference['secnumber'] = number
                    if titlenode:
                        titlenode['secnumber'] = number
                        titlenode = None
                elif isinstance(subnode, addnodes.toctree):
                    _walk_toctree(subnode, depth)

        def _walk_toctree(toctreenode: addnodes.toctree, depth: int) -> None:
            if depth == 0:
                return
            for _title, ref in toctreenode['entries']:
                if url_re.match(ref) or ref == 'self':
                    # don't mess with those
                    continue
                if ref in assigned:
                    logger.warning(
                        __(
                            '%s is already assigned section numbers '
                            '(nested numbered toctree?)'
                        ),
                        ref,
                        location=toctreenode,
                        type='toc',
                        subtype='secnum',
                    )
                elif ref in env.tocs:
                    secnums: dict[str, tuple[int, ...]] = {}
                    env.toc_secnumbers[ref] = secnums
                    assigned.add(ref)
                    _walk_toc(env.tocs[ref], secnums, depth, env.titles.get(ref))
                    if secnums != old_secnumbers.get(ref):
                        rewrite_needed.append(ref)

        for docname in env.numbered_toctrees:
            assigned.add(docname)
            doctree = env.get_doctree(docname)
            for toctreenode in doctree.findall(addnodes.toctree):
                depth = toctreenode.get('numbered', 0)
                if depth:
                    # every numbered toctree gets new numbering
                    numstack = [0]
                    _walk_toctree(toctreenode, depth)

        return rewrite_needed

    def assign_figure_numbers(self, env: BuildEnvironment) -> list[str]:
        """Assign a figure number to each figure under a numbered toctree."""
        generated_docnames = frozenset(env.domains.standard_domain._virtual_doc_names)

        rewrite_needed = []

        assigned: set[str] = set()
        old_fignumbers = env.toc_fignumbers
        env.toc_fignumbers = {}
        fignum_counter: dict[str, dict[tuple[int, ...], int]] = {}

        def get_figtype(node: Node) -> str | None:
            for domain in env.domains.sorted():
                figtype = domain.get_enumerable_node_type(node)
                if isinstance(domain, StandardDomain) and not domain.get_numfig_title(
                    node
                ):
                    # Skip if uncaptioned node
                    continue

                if figtype:
                    return figtype

            return None

        def get_section_number(docname: str, section: nodes.section) -> tuple[int, ...]:
            anchorname = '#' + section['ids'][0]
            secnumbers = env.toc_secnumbers.get(docname, {})
            if anchorname in secnumbers:
                secnum = secnumbers.get(anchorname)
            else:
                secnum = secnumbers.get('')

            return secnum or ()

        def get_next_fignumber(
            figtype: str, secnum: tuple[int, ...]
        ) -> tuple[int, ...]:
            counter = fignum_counter.setdefault(figtype, {})

            secnum = secnum[: env.config.numfig_secnum_depth]
            counter[secnum] = counter.get(secnum, 0) + 1
            return (*secnum, counter[secnum])

        def register_fignumber(
            docname: str, secnum: tuple[int, ...], figtype: str, fignode: Element
        ) -> None:
            env.toc_fignumbers.setdefault(docname, {})
            fignumbers = env.toc_fignumbers[docname].setdefault(figtype, {})
            figure_id = fignode['ids'][0]

            fignumbers[figure_id] = get_next_fignumber(figtype, secnum)

        def _walk_doctree(
            docname: str, doctree: Element, secnum: tuple[int, ...]
        ) -> None:
            nonlocal generated_docnames
            for subnode in doctree.children:
                if isinstance(subnode, nodes.section):
                    next_secnum = get_section_number(docname, subnode)
                    if next_secnum:
                        _walk_doctree(docname, subnode, next_secnum)
                    else:
                        _walk_doctree(docname, subnode, secnum)
                elif isinstance(subnode, addnodes.toctree):
                    for _title, subdocname in subnode['entries']:
                        if url_re.match(subdocname) or subdocname == 'self':
                            # don't mess with those
                            continue
                        if subdocname in generated_docnames:
                            # or these
                            continue

                        _walk_doc(subdocname, secnum)
                elif isinstance(subnode, nodes.Element):
                    figtype = get_figtype(subnode)
                    if figtype and subnode['ids']:
                        register_fignumber(docname, secnum, figtype, subnode)

                    _walk_doctree(docname, subnode, secnum)

        def _walk_doc(docname: str, secnum: tuple[int, ...]) -> None:
            if docname not in assigned:
                assigned.add(docname)
                doctree = env.get_doctree(docname)
                _walk_doctree(docname, doctree, secnum)

        if env.config.numfig:
            _walk_doc(env.config.root_doc, ())
            for docname, fignums in env.toc_fignumbers.items():
                if fignums != old_fignumbers.get(docname):
                    rewrite_needed.append(docname)

        return rewrite_needed


def _make_anchor_name(ids: list[str], num_entries: list[int]) -> str:
    if not num_entries[0]:
        # for the very first toc entry, don't add an anchor
        # as it is the file's title anyway
        anchorname = ''
    else:
        anchorname = '#' + ids[0]
    num_entries[0] += 1
    return anchorname


def setup(app: Sphinx) -> ExtensionMetadata:
    app.add_env_collector(TocTreeCollector)

    return {
        'version': 'builtin',
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }
